M=[r.split(',') for r in raw.split('|')]
S=collections.defaultdict(lambda: collections.defaultdict(int))
NM={'形状記憶日傘':'短','完全遮光・形状記憶':'長'}
for r in csv.DictReader(open('data/daily/daily_sales.csv')):
    if r['name'] in NM: S[NM[r['name']]][r['date']]+=int(r['gross'])-int(r['disc'])
W=[('W-4 7/12-18','2026-07-12','2026-07-18'),('W-3 7/19-25','2026-07-19','2026-07-25'),
   ('W-2 7/26-8/01','2026-07-26','2026-08-01'),('W-1 8/02-08','2026-08-02','2026-08-08')]
print('=== 日傘2種 週次（短=形状記憶 / 長=完全遮光・晴雨兼用UV） ===')
print(f"{'週':14}{'':4}{'広告':>9}{'インプ':>8}{'CTR':>7}{'CPM':>7}{'CPC':>6}{'実売':>10}{'MER':>6}{'売上/CL':>8}")
prev={}
for lbl,a,b in W:
    for k in ['短','長']:
        rows=[m for m in M if m[1]==k and a<=m[0]<=b]
        c=sum(int(x[2]) for x in rows); i=sum(int(x[3]) for x in rows); cl=sum(int(x[4]) for x in rows)
        s=sum(S[k][d] for d in S[k] if a<=d<=b)
        print(f"{lbl if k=='短' else '':14}{k:4}{c:>9,}{i:>8,}{cl/i*100:>6.2f}%{c/i*1000:>7,.0f}{c/cl:>6,.0f}{s:>10,}{s/c:>6.2f}{s/cl:>8,.0f}")
    print()
print('=== CPM比（長÷短）の推移＝自社競合が構造的かの検証 ===')
for lbl,a,b in W:
    r={}
    for k in ['短','長']:
        rows=[m for m in M if m[1]==k and a<=m[0]<=b]
        r[k]=sum(int(x[2]) for x in rows)/sum(int(x[3]) for x in rows)*1000
    print(f"  {lbl:14} 短 {r['短']:>6,.0f} / 長 {r['長']:>6,.0f} → 長は短の {r['長']/r['短']*100:.0f}%")
